var l=[{title:`Τι αλλάζει το φορτίο στα γόνατά σας`,text:`Το βάθος της καθισιάς, το ύψος του σκαλοπατιού, η ισορροπία, η ταχύτητα, η αντίσταση και η κρούση των αλμάτων αλλάζουν όλα το πόσο δουλεύουν τα γόνατά σας. Δεν υπάρχει καθολικός κανόνας ότι το γόνατό σας δεν πρέπει ποτέ να περνά τα δάχτυλα. Το πόσο μπορεί να προχωρήσει άνετα το γόνατό σας διαφέρει ανάμεσα σε ανθρώπους και σε εργασίες.`},{title:`Πρακτικές αντικαταστάσεις`,text:`Ένα ελεγχόμενο σήκωμα από το κάθισμα, ένα split squat με στήριξη ή ένα χαμηλό step-up μπορεί να μαθαίνεται ευκολότερα από ένα γρήγορο άλμα από καθισιά. Μια ρηχότερη ή πιο αργή εκδοχή μπορεί να αισθάνεται πιο άνετα σε ορισμένες περιπτώσεις. Όταν η κρούση είναι πρόβλημα, η φυσική κατάσταση αντοχής χαμηλής κρούσης όπως η ποδηλασία ή το περπάτημα σε επίπεδο έδαφος μπορεί να δουλέψει καλύτερα από τα άλματα.`},{title:`Χτίστε σταδιακά`,text:`Ξεκινήστε με μια κίνηση και μια ποσότητα προπόνησης που ανέχονται τα γόνατά σας. Προσθέστε φορτίο, βάθος ή επαναλήψεις μόνο όσο τα συμπτώματα μένουν αποδεκτά κατά τη διάρκεια και μετά την προπόνηση. Μη δοκιμάζετε συνεχώς μια επώδυνη θέση για να δείτε αν «διορθώθηκε από μόνη της». Η γενική συμβουλή άσκησης δεν είναι διάγνωση ή πρόγραμμα αποκατάστασης.`},{title:`Πότε να ζητήσετε βοήθεια`,text:`Ένα πολύ επώδυνο, ορατά παραμορφωμένο ή πολύ πρησμένο γόνατο, η αδυναμία να πατήσετε πάνω του, το κλείδωμα, ο πυρετός με ερυθρότητα ή τα συμπτώματα μετά από σημαντικό τραυματισμό χρειάζονται άμεση επαγγελματική αξιολόγηση. Και τα προβλήματα που επιμένουν πρέπει να ελέγχονται.`},{title:`Χρήση του TrainUp`,text:`Προσθέστε τα γόνατά σας ως περιορισμό στο Profile, με μια σημείωση, και ορίστε αν επιτρέπονται τα άλματα. Το πρόγραμμα παραλείπει τότε ασκήσεις που δεν ταιριάζουν. Αν μια άσκηση πονά, το «I feel pain» την τελειώνει και την κρατά εκτός των προγραμμάτων σας μέχρι να την επαναφέρετε από το Profile. Καμία άσκηση δεν είναι εγγυημένα «ασφαλής για τα γόνατα» για όλους.`}];var i=[{label:`NHS: πόνος στο γόνατο και πότε να ζητήσετε βοήθεια`,url:`https://www.nhs.uk/symptoms/knee-pain/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:l,sources:i};export{s as default,l as sections,i as sources};